using Microsoft.Dynamics365.LocalizationFramework;
using SL = Microsoft.Dynamics365.LocalizationFramework.XppSupportLayer;
using System.IO;
using Microsoft.WindowsAzure.Storage.Blob;

/// <summary>
/// MPJ_30779_PaymentPlus
/// <c>METERFormatFileAzureStorage</c> manages the import file for 'MET Azure storage' document type
/// </summary>
public class METERFormatFileAzureStorage implements ERIImportFile
{
    private str folderPath;
    private str additionalInfo;
    private str fileId;
    private str name;
    private SL.utcdatetime createdDateTime;
    private SL.utcdatetime modifiedDateTime;
    private str sourceSettingsKey;
    private CloudBlockBlob blob;
    private boolean isDecrypted;
    private DocuType docuType;

}

Method.Source:
    protected void new(str _fileId,
                        str _name,
                        utcdatetime _dateTime,
                        str _folderPath,
                        CloudBlockBlob _blob,
                        boolean _isDecrypted,
                        DocuType    _docuType)
    {
        fileId = _fileId;
        name = _name;
        createdDateTime = ERLFConvert::fromUtcdatetime(_dateTime);
        modifiedDateTime =  ERLFConvert::fromUtcdatetime(_dateTime);
        folderPath = _folderPath;
        blob = _blob;
        isDecrypted = _isDecrypted;
        docuType   = _docuType;
        this.set_SourceSettingsKey(METERImportFormatSourceAzureStorageSettings::SettingsKey);

    }

[Hookable(false)]
public str parmAdditionalInfo(str _additionalInfo = additionalInfo)
{
    additionalInfo = _additionalInfo;
    return additionalInfo;
}

/// <summary>
/// Construct new object.
/// </summary>
/// <param name = "_fileId">File id.</param>
/// <param name = "_name">Name.</param>
/// <param name = "_dateTime">Date time.</param>
/// <param name = "_folderPath">Folder path.</param>
/// <param name = "_blob">Azure blob object.</param>
/// <param name = "_isDecrypted">Use Azure function for decrypt file</param>
/// <param name = "_docuType">Document type used for import.</param>
/// <returns>Import file.</returns>
public static METERFormatFileAzureStorage construct(str _fileId,
    str _name,
    utcdatetime _dateTime,
    str _folderPath,
    CloudBlockBlob _blob,
    boolean _isDecrypted,
    DocuType    _docuType
    )
{
    return new METERFormatFileAzureStorage(_fileId, _name, _dateTime, _folderPath, _blob, _isDecrypted, _docuType);
}

    /// <summary>
    /// Loads the file from the source.
    /// </summary>
    /// <returns>A file operation result.</returns>
    public ERFileLoadResult Load()
    {
        System.Exception exception;
        str errorMessage;
        ERFileLoadResult ret;
        System.Uri sysAccessUri;
        boolean canSelect = System.Uri::TryCreate(blob.SnapshotQualifiedUri.AbsoluteUri, System.UriKind::Absolute, byref sysAccessUri);

        if (!docuType)
        {
            errorMessage = strFmt("@SYS28052", docuType.TypeId);
            ret = ERFileLoadResult::Fail(errorMessage);
        }
        if (docuType.FilePlace != DocuFilePlace::METAzureStorage)
        {
            errorMessage = strFmt("@MET:DocuTypeAzureStorageValidation", docuType.TypeId);
            ret = ERFileLoadResult::Fail(errorMessage);
        }
        if (!errorMessage)
        {
            if (canSelect)
            {
                try
                {
                    System.IO.Stream fileContent = METBlobStorageHelper::download(blob, docuType, isDecrypted);
                    ret = ERFileLoadResult::Success(fileContent);
                }
                catch (Exception::Error)
                {                    
                    errorMessage = Global::METGetErrorAndCLR();

                    ret = ERFileLoadResult::Fail(errorMessage);
                }

            }
            else
            {
                ret = ERFileLoadResult::Fail("@ElectronicReporting:FileCannotBeLoaded");
            }
        }

        return ret;
    }

    /// <summary>
    /// Delete the file from the source location after it is moved to archive or error folder
    /// </summary>
    /// <returns>ERFileDeleteResult</returns>
    public ERFileDeleteResult Delete()
    {
        ERFileDeleteResult ret;
        System.Uri sysAccessUri;
        boolean canSelect = System.Uri::TryCreate(blob.SnapshotQualifiedUri.AbsoluteUri, System.UriKind::Absolute, byref sysAccessUri);

        if (canSelect)
        {
            if (blob)
            {
                if (blob.DeleteIfExists(DeleteSnapshotsOption::None, null, null, null))
                {
                    ret = ERFileDeleteResult::Success();
                }
                else
                {
                    ret = ERFileDeleteResult::Fail("@MET:FileDeleteError");
                }
            }
            else
            {
                ret = ERFileDeleteResult::Fail("@MET:FileDeleteCloudBlockBlobError");
            }
        }
        else
        {
            ret = ERFileDeleteResult::Fail("@ElectronicReporting:FileCannotBeDeleted");
        }

        return ret;
    }
